/*
 * iOS 原生日历风格byRABBIT
 * 使用：完整替换月历原有的自定义美化 CSS，不要与旧贴纸主题叠加。
 * 根据参考资料中已提供的 --cal-* 变量与类名编写。
 * 原应用负责日期、农历、事件、切月和按钮行为。
 */
:root {
  --ios-cal-red: #ff3b45;
  --ios-cal-ink: #111113;
  --ios-cal-muted: #8e8e93;
  --ios-cal-line: #e5e5ea;
  --ios-cal-blue: #91d6ee;
  --ios-cal-font: -apple-system, BlinkMacSystemFont, "Helvetica Neue",
    "PingFang SC", "PingFang TC", system-ui, sans-serif;

  --cal-font: var(--ios-cal-font);
  --cal-page-bg: #ffffff;
  --cal-page-bg-image: none;
  --cal-page-bg-size: cover;
  --cal-page-bg-position: center;
  --cal-page-padding: max(var(--nuo-safe-top, env(safe-area-inset-top, 0px)), 20px)
    16px calc(112px + env(safe-area-inset-bottom, 0px));
  --cal-ink: var(--ios-cal-ink);
  --cal-ink-muted: var(--ios-cal-muted);
  --cal-accent: var(--ios-cal-red);

  --cal-title-color: var(--ios-cal-ink);
  --cal-title-size: 2.15rem;
  --cal-title-weight: 750;
  --cal-title-letter-spacing: -1px;
  --cal-title-font: var(--ios-cal-font);
  --cal-topbar-gap: 14px;
  --cal-avatar-size: 36px;
  --cal-avatar-radius: 50%;
  --cal-avatar-border: 1px solid #eeeeef;
  --cal-avatar-shadow: none;

  --cal-week-color: var(--ios-cal-ink);
  --cal-week-size: 0.72rem;
  --cal-week-weight: 400;
  --cal-week-transform: none;
  --cal-grid-gap: 0px;
  --cal-grid-margin-bottom: 22px;

  --cal-day-bg: transparent;
  --cal-day-radius: 0px;
  --cal-day-border: none;
  --cal-day-shadow: none;
  --cal-day-backdrop-filter: none;
  --cal-day-shine: transparent;
  --cal-day-width: 46px;
  --cal-day-height: 46px;
  --cal-daynum-color: var(--ios-cal-ink);
  --cal-daynum-size: 1.32rem;
  --cal-daynum-weight: 500;
  --cal-today-bg: var(--ios-cal-red);
  --cal-today-color: #ffffff;
  --cal-today-radius: 50%;
  --cal-today-shadow: none;
  --cal-selected-border: 1.5px solid #b8b8bd;
  --cal-selected-transform: none;
  --cal-selected-shadow: none;
  --cal-dot-color: var(--ios-cal-blue);

  --cal-card-bg: #ffffff;
  --cal-card-radius: 20px;
  --cal-card-border: 1px solid var(--ios-cal-line);
  --cal-card-shadow: none;
  --cal-card-backdrop-filter: none;
  --cal-card-padding: 18px;
  --cal-card-title-color: var(--ios-cal-ink);
  --cal-card-title-size: 1.05rem;
  --cal-card-title-weight: 600;
  --cal-item-radius: 12px;
  --cal-item-padding: 12px 14px;
  --cal-item-border: none;
  --cal-item-shadow: none;
  --cal-item-user-bg: #f5f5f7;
  --cal-item-ai-bg: #f0f7fb;
  --cal-item-todo-bg: #f5f5f7;
  --cal-item-header-color: #68686e;
  --cal-item-text-color: var(--ios-cal-ink);

  --cal-nav-bg: rgba(255, 255, 255, 0.88);
  --cal-nav-radius: 32px;
  --cal-nav-border: 1px solid rgba(210, 210, 215, 0.45);
  --cal-nav-shadow: 0 5px 28px rgba(0, 0, 0, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);
  --cal-nav-backdrop-filter: blur(22px) saturate(160%);
  --cal-nav-min-height: 68px;
  --cal-nav-padding-top: 8px;
  --cal-nav-color: #69696f;
  --cal-nav-active-color: var(--ios-cal-red);
  --cal-nav-active-transform: none;
  --cal-nav-label-size: 0.65rem;
  --cal-nav-label-weight: 500;
  --cal-fab-bg: #ffffff;
  --cal-fab-bg-image: none;
  --cal-fab-color: var(--ios-cal-ink);
  --cal-fab-size: 48px;
  --cal-fab-radius: 50%;
  --cal-fab-border: 1px solid #ededf0;
  --cal-fab-shadow: 0 3px 16px rgba(0, 0, 0, 0.07);
  --cal-sticker-size: 15px;
  --cal-sticker-border: 2px solid #ffffff;
  --cal-sticker-marker-bg: var(--ios-cal-blue);
  --cal-sticker-marker-shadow: none;
  --cal-sticker-heart-bg: var(--ios-cal-red);
  --cal-sticker-heart-shadow: none;

  --cal-overlay-bg: rgba(0, 0, 0, 0.25);
  --cal-overlay-backdrop-filter: blur(5px);
  --cal-modal-bg: #ffffff;
  --cal-modal-radius: 26px;
  --cal-modal-border: 1px solid #eeeeef;
  --cal-modal-shadow: 0 18px 60px rgba(0, 0, 0, 0.16);
  --cal-menu-bg: rgba(255, 255, 255, 0.96);
  --cal-menu-radius: 18px;
  --cal-menu-shadow: 0 8px 32px rgba(0, 0, 0, 0.12);
  --cal-menu-item-color: var(--ios-cal-ink);
  --cal-vcal-bg: #f5f5f7;
  --cal-vcal-border: 1px solid var(--ios-cal-line);
  --cal-vcal-label-color: var(--ios-cal-ink);
  --cal-vcal-sub-color: #737379;
  --cal-tag-radius: 8px;
  --cal-tag-border: none;

  --cal-section-title-color: var(--ios-cal-ink);
  --cal-section-title-size: 1.08rem;
  --cal-section-title-weight: 600;
  --cal-now-pill-bg: #fff0f1;
  --cal-now-pill-color: #d92534;
  --cal-now-pill-border: none;
  --cal-now-pill-radius: 999px;
  --cal-tl-line: #e5e5ea;
  --cal-tl-dot-bg: var(--ios-cal-red);
  --cal-tl-dot-border: 2px solid #ffffff;
  --cal-char-card-bg: transparent;
  --cal-char-avatar-size: 48px;
  --cal-char-avatar-radius: 50%;
  --cal-char-avatar-border: 1px solid #eeeeef;
  --cal-char-avatar-shadow: none;
  --cal-tl-header-color: var(--ios-cal-ink);
  --cal-bubble-radius: 14px;
  --cal-bubble-border-color: #e5e5ea;
  --cal-bubble-shadow: none;
  --cal-bubble-title-color: var(--ios-cal-ink);
  --cal-bubble-sub-color: #737379;
  --cal-timeline-ai-bg: #ffffff;
  --cal-timeline-user-bg: #ffffff;
  --cal-agenda-bg: #f5f5f7;
  --cal-agenda-color: var(--ios-cal-ink);
  --cal-agenda-radius: 14px;
  --cal-agenda-shadow: none;
  --cal-agenda-line-color: #e5e5ea;
  --cal-agenda-dot-bg: var(--ios-cal-red);
  --cal-agenda-dot-border: 2px solid #ffffff;
  --cal-stat-header-bg: #f5f5f7;
  --cal-stat-header-radius: 20px;
  --cal-stat-header-backdrop-filter: none;
  --cal-stat-avatar-bg: #eeeeef;
  --cal-stat-avatar-size: 52px;
  --cal-stat-avatar-radius: 50%;
  --cal-stat-name-color: var(--ios-cal-ink);
  --cal-stat-label-color: #737379;
  --cal-stat-bar-bg: #e5e5ea;
  --cal-stat-bar-fill: var(--ios-cal-red);

  --cal-todo-panel-bg: #ffffff;
  --cal-todo-panel-radius: 26px 26px 0 0;
  --cal-todo-panel-shadow: 0 -8px 40px rgba(0, 0, 0, 0.1);
  --cal-todo-radius: 12px;
  --cal-todo-text-color: var(--ios-cal-ink);
  --cal-todo-check-bg: #ffffff;
  --cal-todo-check-border: 1.5px solid #b8b8bd;
  --cal-todo-check-radius: 50%;
  --cal-todo-check-color: var(--ios-cal-red);

  --cal-memory-bg: #ffffff;
  --cal-memory-bg-image: none;
  --cal-memory-title-bg: transparent;
  --cal-memory-title-color: var(--ios-cal-ink);
  --cal-memory-title-border: none;
  --cal-memory-title-radius: 0px;
  --cal-memory-title-shadow: none;
  --cal-memory-title-rotate: none;
  --cal-report-bg: #f5f5f7;
  --cal-report-border: none;
  --cal-report-radius: 22px;
  --cal-report-shadow: none;
  --cal-report-title-color: var(--ios-cal-ink);
  --cal-polaroid-bg: #ffffff;
  --cal-polaroid-border: 1px solid #e5e5ea;
  --cal-polaroid-radius: 18px;
  --cal-polaroid-padding: 8px 8px 14px;
  --cal-polaroid-shadow: none;
  --cal-polaroid-img-bg: #f5f5f7;
  --cal-polaroid-img-radius: 12px;
  --cal-polaroid-caption-color: var(--ios-cal-ink);
  --cal-polaroid-caption-font: var(--ios-cal-font);
  --cal-badge-name-color: var(--ios-cal-ink);
  --cal-badge-avatar-bg: #f5f5f7;
  --cal-badge-avatar-border: 2px solid #ffffff;
  --cal-letter-bg: #f5f5f7;
  --cal-letter-border: none;
}

/* 清除纯装饰插槽，功能按钮与真实内容保留 */
.nuo-cal-decor-topbar,
.nuo-cal-decor-grid-top,
.nuo-cal-decor-grid-bottom,
.nuo-cal-decor-card-top,
.nuo-cal-decor-memory-top {
  display: none !important;
}

.nuo-cal-month,
.nuo-cal-timeline,
.nuo-cal-memory {
  font-family: var(--ios-cal-font);
  color: var(--ios-cal-ink);
  color-scheme: light;
}

/* 标题栏：保持宿主原有导航顺序 */
.nuo-cal-topbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 20px;
}
.nuo-cal-title-wrap {
  position: static;
  transform: none;
  justify-content: flex-start;
  min-width: 0;
  flex: 1 1 auto;
}
.nuo-cal-topbar .month-title {
  font-family: var(--ios-cal-font) !important;
  color: var(--ios-cal-ink);
  font-size: clamp(26px, 7vw, 36px);
  font-weight: 750;
  line-height: 1.15;
  letter-spacing: -1px;
}
.nuo-cal-topbar .back-icon {
  box-sizing: border-box;
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  padding: 10px;
  border-radius: 50%;
  color: var(--ios-cal-ink);
  background: #ffffff;
  box-shadow: 0 4px 22px rgba(0, 0, 0, 0.06);
}
.nuo-cal-topbar .header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 6px;
  border: 1px solid #f2f2f4;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.9);
  box-shadow: 0 5px 25px rgba(0, 0, 0, 0.06);
  -webkit-backdrop-filter: blur(18px);
  backdrop-filter: blur(18px);
}
.nuo-cal-topbar .header-actions button {
  min-width: 40px;
  min-height: 40px;
  color: var(--ios-cal-ink);
  border-radius: 50%;
}

/* 每格上沿组成横向细线，不加纵线。
 * 不指定格内 display，保留宿主的农历/贴纸/事件定位。
 */
.nuo-cal-cell {
  position: relative;
  box-sizing: border-box;
  min-width: 0;
  min-height: clamp(72px, 17.8vw, 90px);
  border-top: 0.5px solid var(--ios-cal-line);
}
.nuo-cal-cell .day-number {
  font-family: var(--ios-cal-font);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.5px;
  line-height: 1.15;
}
/* 使用局部变量，避免直接覆盖今天的白色数字 */
.nuo-cal-cell:is([data-weekday="日"], [data-weekday="六"],
  [data-weekday="周日"], [data-weekday="周六"],
  [data-weekday="週日"], [data-weekday="週六"],
  [data-weekday="星期日"], [data-weekday="星期天"], [data-weekday="星期六"],
  [data-weekday="Sun"], [data-weekday="Sat"],
  [data-weekday="Sunday"], [data-weekday="Saturday"]) {
  --cal-daynum-color: var(--ios-cal-muted);
}

/* 让其他页面与月历统一，保留事件自身的分类颜色 */
.nuo-cal-timeline .section-title,
.nuo-cal-timeline .stat-name,
.nuo-cal-timeline .timeline-header-title,
.nuo-cal-memory .memory-title,
.nuo-cal-memory .report-header,
.nuo-cal-memory .section-title,
.nuo-cal-month .overlap-title-text {
  font-family: var(--ios-cal-font) !important;
  letter-spacing: -0.35px;
}
.nuo-cal-timeline .user-stat-header {
  margin: max(var(--nuo-safe-top, env(safe-area-inset-top, 0px)), 16px)
    16px 20px;
  padding: 18px;
  box-shadow: none;
}
.nuo-cal-timeline .stat-avatar-wrapper {
  border-radius: 50%;
}
.nuo-cal-timeline .stat-avatar {
  object-fit: cover;
}
.nuo-cal-timeline .nuo-cal-time-label {
  color: #737379 !important;
  font-family: var(--ios-cal-font);
  font-variant-numeric: tabular-nums;
}
.nuo-cal-timeline .timeline-bubble.modern-bubble,
.nuo-cal-timeline .agenda-bubble {
  box-shadow: none;
  border-radius: 14px;
}
.nuo-cal-timeline .nuo-cal-note {
  color: #737379 !important;
  font-style: normal !important;
}
.nuo-cal-timeline .todo-comment-box {
  background: #f5f5f7;
  color: #737379;
  border-radius: 10px;
}
.nuo-cal-timeline .user-agenda-list {
  padding-bottom: calc(100px + env(safe-area-inset-bottom, 0px));
}
.nuo-cal-memory .polaroid-item,
.nuo-cal-memory .message-letter-paper {
  transform: none !important;
}
.nuo-cal-memory .tape-strip,
.nuo-cal-memory .mochi-report-card::before {
  display: none;
}
.nuo-cal-memory .caption-date {
  color: #737379;
}

/* 底栏不改成假按钮，保留原本的导航与加号 */
.nuo-cal-nav-btn {
  min-height: 44px;
  gap: 4px;
  -webkit-tap-highlight-color: transparent;
}
.nuo-cal-nav-btn > svg {
  width: 24px;
  height: 24px;
  stroke-width: 1.8;
}
.nuo-cal-nav-btn span {
  font-family: var(--ios-cal-font);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0;
}
.nuo-cal-nav-btn.active::after {
  content: none;
}
.nuo-cal-nav-btn .add-button,
.add-button:has(> svg) {
  margin-top: 0;
  background-image: none;
}
.nuo-cal-nav-btn:focus-visible,
.nuo-cal-topbar button:focus-visible,
.nuo-cal-cell:focus-visible {
  outline: 2px solid #007aff;
  outline-offset: 3px;
}

/* 小屏幕上维持七列，避免日期圆点相互挤压 */
@media (max-width: 360px) {
  :root {
    --cal-day-width: 40px;
    --cal-day-height: 40px;
    --cal-daynum-size: 1.2rem;
    --cal-title-size: 1.75rem;
  }
  .nuo-cal-topbar {
    gap: 8px;
  }
  .nuo-cal-topbar .header-actions {
    gap: 2px;
    padding: 3px;
  }
}

/* 关闭透明效果时的可读性兜底 */
@media (prefers-reduced-transparency: reduce) {
  :root {
    --cal-nav-bg: #ffffff;
    --cal-nav-backdrop-filter: none;
    --cal-menu-bg: #ffffff;
    --cal-overlay-backdrop-filter: none;
  }
  .nuo-cal-topbar .header-actions {
    background: #ffffff;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}

/* 第二轮：月份独占第二行，透明底栏与独立玻璃按钮 */
:root {
  --cal-title-size: 38px;
  --cal-nav-bg: transparent;
  --cal-nav-border: none;
  --cal-nav-shadow: none;
  --cal-nav-backdrop-filter: none;
  --cal-nav-radius: 0px;
  --cal-nav-min-height: 72px;
  --cal-nav-color: #333338;
  --cal-fab-bg: rgba(255,255,255,.58);
  --cal-fab-border: 1px solid rgba(255,255,255,.85);
  --cal-fab-shadow: inset 0 1px 1px #fff, 0 5px 20px rgba(0,0,0,.08);
}
.nuo-cal-topbar {
  display: flex !important;
  flex-wrap: wrap !important;
  align-items: center;
  justify-content: space-between;
  column-gap: 12px;
  row-gap: 22px;
  margin-bottom: 16px;
}
.nuo-cal-topbar .back-icon { order: 1; }
.nuo-cal-topbar .header-actions { order: 2; margin-left: auto; }
.nuo-cal-topbar .nuo-cal-title-wrap {
  order: 3;
  position: static !important;
  inset: auto !important;
  transform: none !important;
  flex: 0 0 100% !important;
  width: 100%;
  box-sizing: border-box;
  margin: 0 !important;
  padding: 0 4px;
  justify-content: flex-start !important;
  text-align: left !important;
}
.nuo-cal-topbar .month-title {
  margin: 0;
  font-size: clamp(34px, 8.5vw, 42px) !important;
  font-weight: 750;
  line-height: 1.18;
  text-align: left;
}
.nuo-cal-nav-btn {
  box-sizing: border-box;
  min-width: 48px;
  min-height: 52px;
  padding: 7px 10px;
  border: 1px solid rgba(255,255,255,.8);
  border-radius: 999px;
  background: rgba(255,255,255,.52);
  box-shadow: inset 0 1px 1px rgba(255,255,255,.95),
    inset 0 -1px 1px rgba(180,185,195,.15), 0 5px 20px rgba(0,0,0,.07);
  -webkit-backdrop-filter: blur(18px) saturate(155%);
  backdrop-filter: blur(18px) saturate(155%);
}
/* 加号在导航按钮内部时，只保留外层一份玻璃，避免双重边框 */
.nuo-cal-nav-btn .add-button {
  background: transparent;
  border: 0;
  box-shadow: none;
}
@media (prefers-reduced-transparency: reduce) {
  .nuo-cal-nav-btn {
    background: #fff;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
    border-color: #e5e5ea;
  }
}

/* 第三轮：使用已确认的 class hook。农历需宿主提供数据。 */
.nuo-cal-topbar > .nuo-cal-title {
  order: 3;
  flex: 0 0 100%;
  position: static !important;
  transform: none !important;
  margin: 0;
  text-align: left;
}
.nuo-cal-topbar .nuo-cal-title {
  font-family: var(--ios-cal-font);
  font-size: clamp(34px, 8.5vw, 42px);
  line-height: 1.18;
  font-weight: 750;
  letter-spacing: -1px;
}
/* 用月中第15日识别，避免相邻月份补位格干扰。
   只有带真实日格的日期才参与匹配；旧浏览器保持数字标题。 */
@supports selector(:has(*)) {
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-01-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "一月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-02-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "二月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-03-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "三月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-04-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "四月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-05-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "五月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-06-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "六月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-07-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "七月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-08-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "八月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-09-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "九月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-10-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "十月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-11-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "十一月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-12-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "十二月"; --ios-month-original-size: 0px; }
  .nuo-cal-month .nuo-cal-topbar :is(.nuo-cal-title, .month-title) {
    font-size: var(--ios-month-original-size, clamp(34px, 8.5vw, 42px)) !important;
  }
  .nuo-cal-month .nuo-cal-topbar :is(.nuo-cal-title, .month-title)::after {
    content: var(--ios-month-label, none);
    font-size: clamp(34px, 8.5vw, 42px);
    line-height: 1.18;
    pointer-events: none;
  }
}
/* 生日：去掉格子背景及伪元素蛋糕，不删除日期节点或点击目标。 */
.nuo-cal-day.birthday-day {
  position: relative;
  background: transparent !important;
  border: 0 !important;
  border-radius: 50% !important;
  box-shadow: none !important;
  filter: none !important;
  animation: none !important;
  overflow: visible !important;
  color: var(--cal-daynum-color);
}
.nuo-cal-day.birthday-day::before {
  content: none !important;
  display: none !important;
}
/* 保留生日格的真实子节点，避免隐藏宿主未标注的日期数字。 */
.nuo-cal-day.birthday-day :is(.nuo-cal-daynum, .day-number) {
  position: relative;
  z-index: 1;
  color: var(--cal-daynum-color) !important;
  background: none !important;
  text-shadow: none !important;
  font-size: var(--cal-daynum-size);
}
.nuo-cal-day.birthday-day::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  inset: auto auto -8px 50% !important;
  width: 5px !important;
  height: 5px !important;
  padding: 0 !important;
  margin: 0 !important;
  border: 0 !important;
  border-radius: 50% !important;
  background: var(--ios-cal-blue) !important;
  box-shadow: none !important;
  transform: translateX(-50%) !important;
  animation: none !important;
  pointer-events: none;
}
.nuo-cal-day.birthday-day.today {
  background: var(--ios-cal-red) !important;
}
.nuo-cal-day.birthday-day.today :is(.nuo-cal-daynum, .day-number) {
  color: #fff !important;
}
.nuo-cal-cell:is([data-selected="true"], [data-selected=""], [data-selected="1"]) .nuo-cal-day.birthday-day {
  outline: 1.5px solid #b8b8bd;
  outline-offset: 2px;
}
/* 导航底板透明；原定位与点击行为由宿主保持。 */
.nuo-cal-nav {
  background: transparent !important;
  background-image: none !important;
  border: 0 !important;
  box-shadow: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  gap: 8px;
  padding-left: 12px;
  padding-right: 12px;
  padding-bottom: max(12px, env(safe-area-inset-bottom, 0px));
}
.nuo-cal-nav::before, .nuo-cal-nav::after {
  content: none !important;
}
.nuo-cal-nav .nuo-cal-nav-btn {
  flex: 0 1 64px;
  color: var(--cal-nav-color);
}
.nuo-cal-nav .nuo-cal-nav-btn.active {
  color: var(--ios-cal-red);
  background: rgba(255,255,255,.7);
}
.nuo-cal-nav .nuo-cal-add {
  box-sizing: border-box;
  flex-shrink: 0;
  width: 52px;
  height: 52px;
  margin-top: 0;
  color: var(--ios-cal-ink);
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,.85);
  background: rgba(255,255,255,.58);
  box-shadow: inset 0 1px 1px #fff, 0 5px 20px rgba(0,0,0,.08);
  -webkit-backdrop-filter: blur(18px) saturate(155%);
  backdrop-filter: blur(18px) saturate(155%);
}
.nuo-cal-nav .nuo-cal-nav-btn .nuo-cal-add {
  background: transparent;
  border: 0;
  box-shadow: none;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}
@media (prefers-reduced-transparency: reduce) {
  .nuo-cal-nav .nuo-cal-nav-btn,
  .nuo-cal-nav .nuo-cal-add {
    background: #fff;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}
/* 标题恢复采用 IG 的直接 hook，独占导航下方一行。 */
.nuo-cal-title-wrap {
  position: static !important;
  inset: auto !important;
  transform: none !important;
  display: flex !important;
  justify-content: flex-start !important;
  align-items: center !important;
  text-align: left !important;
  order: 3 !important;
  flex: 0 0 100% !important;
  width: 100% !important;
  min-width: 0 !important;
  margin: 0 auto 0 0 !important;
  padding: 0 !important;
}
.nuo-cal-title, .month-title {
  position: static !important;
  inset: auto !important;
  transform: none !important;
  text-align: left !important;
  justify-content: flex-start !important;
  margin: 0 auto 0 0 !important;
  font-family: var(--ios-cal-font) !important;
  font-size: clamp(34px, 8.5vw, 42px) !important;
  line-height: 1.18 !important;
  font-weight: 750 !important;
}
/* 中文替换尚未在宿主命中，暂保留真实标题，避免空白或重复。 */
.nuo-cal-month .nuo-cal-topbar :is(.nuo-cal-title, .month-title) {
  font-size: clamp(34px, 8.5vw, 42px) !important;
}
.nuo-cal-month .nuo-cal-topbar :is(.nuo-cal-title, .month-title)::after {
  content: none !important;
}
/* 不隐藏未知子节点：生日数字可能与蛋糕共用一层。 */

/*
 * iOS 原生日历风格byRABBIT
 * 使用：完整替换月历原有的自定义美化 CSS，不要与旧贴纸主题叠加。
 * 根据参考资料中已提供的 --cal-* 变量与类名编写。
 * 原应用负责日期、农历、事件、切月和按钮行为。
 */
:root {
  --ios-cal-red: #ff3b45;
  --ios-cal-ink: #111113;
  --ios-cal-muted: #8e8e93;
  --ios-cal-line: #e5e5ea;
  --ios-cal-blue: #91d6ee;
  --ios-cal-font: -apple-system, BlinkMacSystemFont, "Helvetica Neue",
    "PingFang SC", "PingFang TC", system-ui, sans-serif;

  --cal-font: var(--ios-cal-font);
  --cal-page-bg: #ffffff;
  --cal-page-bg-image: none;
  --cal-page-bg-size: cover;
  --cal-page-bg-position: center;
  --cal-page-padding: max(var(--nuo-safe-top, env(safe-area-inset-top, 0px)), 20px)
    16px calc(112px + env(safe-area-inset-bottom, 0px));
  --cal-ink: var(--ios-cal-ink);
  --cal-ink-muted: var(--ios-cal-muted);
  --cal-accent: var(--ios-cal-red);

  --cal-title-color: var(--ios-cal-ink);
  --cal-title-size: 2.15rem;
  --cal-title-weight: 750;
  --cal-title-letter-spacing: -1px;
  --cal-title-font: var(--ios-cal-font);
  --cal-topbar-gap: 14px;
  --cal-avatar-size: 36px;
  --cal-avatar-radius: 50%;
  --cal-avatar-border: 1px solid #eeeeef;
  --cal-avatar-shadow: none;

  --cal-week-color: var(--ios-cal-ink);
  --cal-week-size: 0.72rem;
  --cal-week-weight: 400;
  --cal-week-transform: none;
  --cal-grid-gap: 0px;
  --cal-grid-margin-bottom: 22px;

  --cal-day-bg: transparent;
  --cal-day-radius: 0px;
  --cal-day-border: none;
  --cal-day-shadow: none;
  --cal-day-backdrop-filter: none;
  --cal-day-shine: transparent;
  --cal-day-width: 46px;
  --cal-day-height: 46px;
  --cal-daynum-color: var(--ios-cal-ink);
  --cal-daynum-size: 1.32rem;
  --cal-daynum-weight: 500;
  --cal-today-bg: var(--ios-cal-red);
  --cal-today-color: #ffffff;
  --cal-today-radius: 50%;
  --cal-today-shadow: none;
  --cal-selected-border: 1.5px solid #b8b8bd;
  --cal-selected-transform: none;
  --cal-selected-shadow: none;
  --cal-dot-color: var(--ios-cal-blue);

  --cal-card-bg: #ffffff;
  --cal-card-radius: 20px;
  --cal-card-border: 1px solid var(--ios-cal-line);
  --cal-card-shadow: none;
  --cal-card-backdrop-filter: none;
  --cal-card-padding: 18px;
  --cal-card-title-color: var(--ios-cal-ink);
  --cal-card-title-size: 1.05rem;
  --cal-card-title-weight: 600;
  --cal-item-radius: 12px;
  --cal-item-padding: 12px 14px;
  --cal-item-border: none;
  --cal-item-shadow: none;
  --cal-item-user-bg: #f5f5f7;
  --cal-item-ai-bg: #f0f7fb;
  --cal-item-todo-bg: #f5f5f7;
  --cal-item-header-color: #68686e;
  --cal-item-text-color: var(--ios-cal-ink);

  --cal-nav-bg: rgba(255, 255, 255, 0.88);
  --cal-nav-radius: 32px;
  --cal-nav-border: 1px solid rgba(210, 210, 215, 0.45);
  --cal-nav-shadow: 0 5px 28px rgba(0, 0, 0, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);
  --cal-nav-backdrop-filter: blur(22px) saturate(160%);
  --cal-nav-min-height: 68px;
  --cal-nav-padding-top: 8px;
  --cal-nav-color: #69696f;
  --cal-nav-active-color: var(--ios-cal-red);
  --cal-nav-active-transform: none;
  --cal-nav-label-size: 0.65rem;
  --cal-nav-label-weight: 500;
  --cal-fab-bg: #ffffff;
  --cal-fab-bg-image: none;
  --cal-fab-color: var(--ios-cal-ink);
  --cal-fab-size: 48px;
  --cal-fab-radius: 50%;
  --cal-fab-border: 1px solid #ededf0;
  --cal-fab-shadow: 0 3px 16px rgba(0, 0, 0, 0.07);
  --cal-sticker-size: 15px;
  --cal-sticker-border: 2px solid #ffffff;
  --cal-sticker-marker-bg: var(--ios-cal-blue);
  --cal-sticker-marker-shadow: none;
  --cal-sticker-heart-bg: var(--ios-cal-red);
  --cal-sticker-heart-shadow: none;

  --cal-overlay-bg: rgba(0, 0, 0, 0.25);
  --cal-overlay-backdrop-filter: blur(5px);
  --cal-modal-bg: #ffffff;
  --cal-modal-radius: 26px;
  --cal-modal-border: 1px solid #eeeeef;
  --cal-modal-shadow: 0 18px 60px rgba(0, 0, 0, 0.16);
  --cal-menu-bg: rgba(255, 255, 255, 0.96);
  --cal-menu-radius: 18px;
  --cal-menu-shadow: 0 8px 32px rgba(0, 0, 0, 0.12);
  --cal-menu-item-color: var(--ios-cal-ink);
  --cal-vcal-bg: #f5f5f7;
  --cal-vcal-border: 1px solid var(--ios-cal-line);
  --cal-vcal-label-color: var(--ios-cal-ink);
  --cal-vcal-sub-color: #737379;
  --cal-tag-radius: 8px;
  --cal-tag-border: none;

  --cal-section-title-color: var(--ios-cal-ink);
  --cal-section-title-size: 1.08rem;
  --cal-section-title-weight: 600;
  --cal-now-pill-bg: #fff0f1;
  --cal-now-pill-color: #d92534;
  --cal-now-pill-border: none;
  --cal-now-pill-radius: 999px;
  --cal-tl-line: #e5e5ea;
  --cal-tl-dot-bg: var(--ios-cal-red);
  --cal-tl-dot-border: 2px solid #ffffff;
  --cal-char-card-bg: transparent;
  --cal-char-avatar-size: 48px;
  --cal-char-avatar-radius: 50%;
  --cal-char-avatar-border: 1px solid #eeeeef;
  --cal-char-avatar-shadow: none;
  --cal-tl-header-color: var(--ios-cal-ink);
  --cal-bubble-radius: 14px;
  --cal-bubble-border-color: #e5e5ea;
  --cal-bubble-shadow: none;
  --cal-bubble-title-color: var(--ios-cal-ink);
  --cal-bubble-sub-color: #737379;
  --cal-timeline-ai-bg: #ffffff;
  --cal-timeline-user-bg: #ffffff;
  --cal-agenda-bg: #f5f5f7;
  --cal-agenda-color: var(--ios-cal-ink);
  --cal-agenda-radius: 14px;
  --cal-agenda-shadow: none;
  --cal-agenda-line-color: #e5e5ea;
  --cal-agenda-dot-bg: var(--ios-cal-red);
  --cal-agenda-dot-border: 2px solid #ffffff;
  --cal-stat-header-bg: #f5f5f7;
  --cal-stat-header-radius: 20px;
  --cal-stat-header-backdrop-filter: none;
  --cal-stat-avatar-bg: #eeeeef;
  --cal-stat-avatar-size: 52px;
  --cal-stat-avatar-radius: 50%;
  --cal-stat-name-color: var(--ios-cal-ink);
  --cal-stat-label-color: #737379;
  --cal-stat-bar-bg: #e5e5ea;
  --cal-stat-bar-fill: var(--ios-cal-red);

  --cal-todo-panel-bg: #ffffff;
  --cal-todo-panel-radius: 26px 26px 0 0;
  --cal-todo-panel-shadow: 0 -8px 40px rgba(0, 0, 0, 0.1);
  --cal-todo-radius: 12px;
  --cal-todo-text-color: var(--ios-cal-ink);
  --cal-todo-check-bg: #ffffff;
  --cal-todo-check-border: 1.5px solid #b8b8bd;
  --cal-todo-check-radius: 50%;
  --cal-todo-check-color: var(--ios-cal-red);

  --cal-memory-bg: #ffffff;
  --cal-memory-bg-image: none;
  --cal-memory-title-bg: transparent;
  --cal-memory-title-color: var(--ios-cal-ink);
  --cal-memory-title-border: none;
  --cal-memory-title-radius: 0px;
  --cal-memory-title-shadow: none;
  --cal-memory-title-rotate: none;
  --cal-report-bg: #f5f5f7;
  --cal-report-border: none;
  --cal-report-radius: 22px;
  --cal-report-shadow: none;
  --cal-report-title-color: var(--ios-cal-ink);
  --cal-polaroid-bg: #ffffff;
  --cal-polaroid-border: 1px solid #e5e5ea;
  --cal-polaroid-radius: 18px;
  --cal-polaroid-padding: 8px 8px 14px;
  --cal-polaroid-shadow: none;
  --cal-polaroid-img-bg: #f5f5f7;
  --cal-polaroid-img-radius: 12px;
  --cal-polaroid-caption-color: var(--ios-cal-ink);
  --cal-polaroid-caption-font: var(--ios-cal-font);
  --cal-badge-name-color: var(--ios-cal-ink);
  --cal-badge-avatar-bg: #f5f5f7;
  --cal-badge-avatar-border: 2px solid #ffffff;
  --cal-letter-bg: #f5f5f7;
  --cal-letter-border: none;
}

/* 清除纯装饰插槽，功能按钮与真实内容保留 */
.nuo-cal-decor-topbar,
.nuo-cal-decor-grid-top,
.nuo-cal-decor-grid-bottom,
.nuo-cal-decor-card-top,
.nuo-cal-decor-memory-top {
  display: none !important;
}

.nuo-cal-month,
.nuo-cal-timeline,
.nuo-cal-memory {
  font-family: var(--ios-cal-font);
  color: var(--ios-cal-ink);
  color-scheme: light;
}

/* 标题栏：保持宿主原有导航顺序 */
.nuo-cal-topbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 20px;
}
.nuo-cal-title-wrap {
  position: static;
  transform: none;
  justify-content: flex-start;
  min-width: 0;
  flex: 1 1 auto;
}
.nuo-cal-topbar .month-title {
  font-family: var(--ios-cal-font) !important;
  color: var(--ios-cal-ink);
  font-size: clamp(26px, 7vw, 36px);
  font-weight: 750;
  line-height: 1.15;
  letter-spacing: -1px;
}
.nuo-cal-topbar .back-icon {
  box-sizing: border-box;
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  padding: 10px;
  border-radius: 50%;
  color: var(--ios-cal-ink);
  background: #ffffff;
  box-shadow: 0 4px 22px rgba(0, 0, 0, 0.06);
}
.nuo-cal-topbar .header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 6px;
  border: 1px solid #f2f2f4;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.9);
  box-shadow: 0 5px 25px rgba(0, 0, 0, 0.06);
  -webkit-backdrop-filter: blur(18px);
  backdrop-filter: blur(18px);
}
.nuo-cal-topbar .header-actions button {
  min-width: 40px;
  min-height: 40px;
  color: var(--ios-cal-ink);
  border-radius: 50%;
}

/* 每格上沿组成横向细线，不加纵线。
 * 不指定格内 display，保留宿主的农历/贴纸/事件定位。
 */
.nuo-cal-cell {
  position: relative;
  box-sizing: border-box;
  min-width: 0;
  min-height: clamp(72px, 17.8vw, 90px);
  border-top: 0.5px solid var(--ios-cal-line);
}
.nuo-cal-cell .day-number {
  font-family: var(--ios-cal-font);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.5px;
  line-height: 1.15;
}
/* 使用局部变量，避免直接覆盖今天的白色数字 */
.nuo-cal-cell:is([data-weekday="日"], [data-weekday="六"],
  [data-weekday="周日"], [data-weekday="周六"],
  [data-weekday="週日"], [data-weekday="週六"],
  [data-weekday="星期日"], [data-weekday="星期天"], [data-weekday="星期六"],
  [data-weekday="Sun"], [data-weekday="Sat"],
  [data-weekday="Sunday"], [data-weekday="Saturday"]) {
  --cal-daynum-color: var(--ios-cal-muted);
}

/* 让其他页面与月历统一，保留事件自身的分类颜色 */
.nuo-cal-timeline .section-title,
.nuo-cal-timeline .stat-name,
.nuo-cal-timeline .timeline-header-title,
.nuo-cal-memory .memory-title,
.nuo-cal-memory .report-header,
.nuo-cal-memory .section-title,
.nuo-cal-month .overlap-title-text {
  font-family: var(--ios-cal-font) !important;
  letter-spacing: -0.35px;
}
.nuo-cal-timeline .user-stat-header {
  margin: max(var(--nuo-safe-top, env(safe-area-inset-top, 0px)), 16px)
    16px 20px;
  padding: 18px;
  box-shadow: none;
}
.nuo-cal-timeline .stat-avatar-wrapper {
  border-radius: 50%;
}
.nuo-cal-timeline .stat-avatar {
  object-fit: cover;
}
.nuo-cal-timeline .nuo-cal-time-label {
  color: #737379 !important;
  font-family: var(--ios-cal-font);
  font-variant-numeric: tabular-nums;
}
.nuo-cal-timeline .timeline-bubble.modern-bubble,
.nuo-cal-timeline .agenda-bubble {
  box-shadow: none;
  border-radius: 14px;
}
.nuo-cal-timeline .nuo-cal-note {
  color: #737379 !important;
  font-style: normal !important;
}
.nuo-cal-timeline .todo-comment-box {
  background: #f5f5f7;
  color: #737379;
  border-radius: 10px;
}
.nuo-cal-timeline .user-agenda-list {
  padding-bottom: calc(100px + env(safe-area-inset-bottom, 0px));
}
.nuo-cal-memory .polaroid-item,
.nuo-cal-memory .message-letter-paper {
  transform: none !important;
}
.nuo-cal-memory .tape-strip,
.nuo-cal-memory .mochi-report-card::before {
  display: none;
}
.nuo-cal-memory .caption-date {
  color: #737379;
}

/* 底栏不改成假按钮，保留原本的导航与加号 */
.nuo-cal-nav-btn {
  min-height: 44px;
  gap: 4px;
  -webkit-tap-highlight-color: transparent;
}
.nuo-cal-nav-btn > svg {
  width: 24px;
  height: 24px;
  stroke-width: 1.8;
}
.nuo-cal-nav-btn span {
  font-family: var(--ios-cal-font);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0;
}
.nuo-cal-nav-btn.active::after {
  content: none;
}
.nuo-cal-nav-btn .add-button,
.add-button:has(> svg) {
  margin-top: 0;
  background-image: none;
}
.nuo-cal-nav-btn:focus-visible,
.nuo-cal-topbar button:focus-visible,
.nuo-cal-cell:focus-visible {
  outline: 2px solid #007aff;
  outline-offset: 3px;
}

/* 小屏幕上维持七列，避免日期圆点相互挤压 */
@media (max-width: 360px) {
  :root {
    --cal-day-width: 40px;
    --cal-day-height: 40px;
    --cal-daynum-size: 1.2rem;
    --cal-title-size: 1.75rem;
  }
  .nuo-cal-topbar {
    gap: 8px;
  }
  .nuo-cal-topbar .header-actions {
    gap: 2px;
    padding: 3px;
  }
}

/* 关闭透明效果时的可读性兜底 */
@media (prefers-reduced-transparency: reduce) {
  :root {
    --cal-nav-bg: #ffffff;
    --cal-nav-backdrop-filter: none;
    --cal-menu-bg: #ffffff;
    --cal-overlay-backdrop-filter: none;
  }
  .nuo-cal-topbar .header-actions {
    background: #ffffff;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}

/* 第二轮：月份独占第二行，透明底栏与独立玻璃按钮 */
:root {
  --cal-title-size: 38px;
  --cal-nav-bg: transparent;
  --cal-nav-border: none;
  --cal-nav-shadow: none;
  --cal-nav-backdrop-filter: none;
  --cal-nav-radius: 0px;
  --cal-nav-min-height: 72px;
  --cal-nav-color: #333338;
  --cal-fab-bg: rgba(255,255,255,.58);
  --cal-fab-border: 1px solid rgba(255,255,255,.85);
  --cal-fab-shadow: inset 0 1px 1px #fff, 0 5px 20px rgba(0,0,0,.08);
}
.nuo-cal-topbar {
  display: flex !important;
  flex-wrap: wrap !important;
  align-items: center;
  justify-content: space-between;
  column-gap: 12px;
  row-gap: 22px;
  margin-bottom: 16px;
}
.nuo-cal-topbar .back-icon { order: 1; }
.nuo-cal-topbar .header-actions { order: 2; margin-left: auto; }
.nuo-cal-topbar .nuo-cal-title-wrap {
  order: 3;
  position: static !important;
