:root {
  /* === 布局：方形头像 + 气泡下置 === */
  --plain-avatar-gap: 0px;
  --plain-padding-left-me: 0px;
  --plain-padding-right-them: 0px;
  --plain-avatar-size: 34px;
  --plain-avatar-radius: 0px;
  --plain-gap-within-group: 4px;
  --plain-gap-between-groups: 20px;
  --avatar-shadow: 0 1px 3px rgba(0,0,0,0.12);

  /* === 我方气泡：浅白=== */
  --bubble-me-bg: #f5f5f5;
  --bubble-me-bg-gradient: linear-gradient(90deg, 
    rgba(255, 255, 255, 0.7) 0%,
    rgba(250, 250, 250, 0.8) 20%,
    rgba(235, 235, 235, 0.85) 50%,
    rgba(220, 220, 220, 0.9) 75%,
    rgba(200, 200, 200, 0.95) 100%
  );
  --bubble-me-color: #000000;
  --bubble-me-font-size: 15px;
  --bubble-me-line-height: 1.5;
  --bubble-me-padding: 6px 18px;
  --bubble-me-radius: 2px;
  --bubble-me-radius-first: 8px 8px 2px 8px;
  --bubble-me-radius-mid: 8px 2px 2px 8px;
  --bubble-me-radius-last: 8px 2px 8px 8px;
  --bubble-me-shadow: 0 6px 18px rgba(255, 255, 255, 0.2);
  --bubble-me-border: 0.5px solid #aaaaaa;
  --bubble-me-link-color: #ffffff;

  /* === 对方气泡=== */
  --bubble-them-bg: #f2f2f2;
  --bubble-them-bg-gradient: linear-gradient(90deg, 
    rgba(240, 240, 240, 1) 0%,       
    rgba(245, 245, 245, 0.9) 30%,
    rgba(250, 250, 250, 0.85) 60%,
    rgba(253, 253, 253, 0.8) 85%,
    rgba(255, 255, 255, 0.75) 100%   
  );
  --bubble-them-color: #000000;
  --bubble-them-font-size: 15px;
  --bubble-them-line-height: 1.5;
  --bubble-them-padding: 6px 18px;
  --bubble-them-radius: 2px;
  --bubble-them-radius-first: 8px 8px 8px 2px;
  --bubble-them-radius-mid: 2px 8px 8px 2px;
  --bubble-them-radius-last: 2px 8px 8px 8px;
  --bubble-them-shadow: none;
  --bubble-them-border: 0.8px solid #002fa7;
  --bubble-them-link-color: #002fa7;
}

