.msg-reply-detached-me .msg-reply-detached-text::before {
    content: "";
    position: absolute;
    left: -20px;
    bottom: -42px;
    width: 100px;
    height: 80px;
    background: url("https://i.postimg.cc/rpSZPJbb/wu-biao-ti8.png") no-repeat center/contain;
    pointer-events: none;
    z-index: 0;
    opacity: 0.8;
}

/* L 线挂外层，固定不动 */
.msg-reply-detached-me .msg-reply-detached-text::after {
    display: none !important;
}

.msg-reply-detached-me::after {
    content: "";
    position: absolute;
    left: -12px;
    bottom: -30px;
    width: 100px;
    height: 14px;
    border-left: 1px solid #888888;
    border-bottom: 1px solid #888888;
    pointer-events: none;
    z-index: 1;
}

/* ===== 对方 ===== */
.msg-reply-detached-them {
    position: relative !important;
    overflow: visible !important;
    align-self: flex-start !important;
    align-self: flex-start !important;
    transform: translateX(120px) !important;
}

.msg-reply-detached-them .msg-reply-detached-text {
    color: #4a4a4a !important;
    font-size: 14px !important;
    max-width: 80vw !important;
    box-shadow: inset 0 0 0 1px #002fa7 !important;
    word-break: break-word !important;
    white-space: pre-wrap !important;
}

.msg-reply-detached-them .msg-reply-detached-text::before {
    content: "";
    position: absolute;
    right: -20px;
    bottom: -42px;
    width: 100px;
    height: 80px;
    background: url("https://i.postimg.cc/mrQp5wqJ/wu-biao-ti8-2.png") no-repeat center/contain;
    pointer-events: none;
    z-index: 0;
    opacity: 0.8;
}

/* L 线挂外层，固定不动 */
.msg-reply-detached-them .msg-reply-detached-text::after {
    display: none !important;
}

.msg-reply-detached-them::after {
    content: "";
    position: absolute;
    right: -12px;
    bottom: -30px;
    width: 100px;
    height: 14px;
    border-right: 1px solid #002fa7;
    border-bottom: 1px solid #002fa7;
    pointer-events: none;
    z-index: 1;
}

/* 非文本消息去边框 */
.bubble-me-custom:has(img):not(:has(.voice-msg)),
.bubble-me-custom:has(.msg-image):not(:has(.voice-msg)),
.bubble-them-custom:has(img):not(:has(.voice-msg)),
.bubble-them-custom:has(.msg-image):not(:has(.voice-msg)),
.bubble-me-custom:has([class*="card"]):not(:has(.voice-msg)),
.bubble-them-custom:has([class*="card"]):not(:has(.voice-msg)),
.bubble-me-custom:has([class*="transfer"]):not(:has(.voice-msg)),
.bubble-them-custom:has([class*="transfer"]):not(:has(.voice-msg)),
.bubble-me-custom:has([class*="gift"]):not(:has(.voice-msg)),
.bubble-them-custom:has([class*="gift"]):not(:has(.voice-msg)) {
    border: none !important;
    background: transparent !important;
    box-shadow: none !important;
}

custom.css:
:root {
  /* 🌞 白天：亮色晨曦渐变 (从上到下，明亮且不刺眼) */
  --bg-gradient: linear-gradient(180deg, #fdf4e3 0%, #e7d6ee 100%);
  --glass-base: rgba(255, 255, 255, 0.65);
  --card-border: rgba(184, 134, 11, 0.7);
  --card-glow: rgba(184, 134, 11, 0.15);
  --text-main: #3a2e39; 
  --text-sub: #6b5b6b;
  --mask-overlay: linear-gradient(180deg, rgba(253, 244, 227, 0.8) 0%, rgba(231, 214, 238, 0.4) 40%, rgba(231, 214, 238, 0.95) 100%);
  --accent-glow: rgba(184, 134, 11, 0.4);
}

@media (prefers-color-scheme: dark) {
  :root {
    /* 🌙 夜晚：深邃蓝宝石 + 星尘紫渐变 (保持原样，完美未动) */
    --bg-gradient: linear-gradient(135deg, #0f172a 0%, #1e1b4b 50%, #2e1065 100%);
    --glass-base: rgba(15, 23, 42, 0.65);
    --card-border: rgba(168, 85, 247, 0.6);
    --card-glow: rgba(139, 92, 246, 0.2);
    --text-main: #e2e8f0; 
    --text-sub: #94a3b8;
    --mask-overlay: linear-gradient(180deg, rgba(15, 23, 42, 0.8) 0%, rgba(30, 27, 75, 0.4) 30%, rgba(46, 16, 101, 0.95) 100%);
    --accent-glow: rgba(139, 92, 246, 0.4);
  }
}

.page { 
  position: absolute; 
  inset: 0; 
  color: var(--text-main); 
  font-family: "Georgia", "Songti SC", serif; 
  overflow: hidden;
  background: var(--bg-gradient);
}

/* 背景 */
.bg-blur {
  position: absolute; inset: -20px; background-position: center; background-size: cover;
  filter: blur(40px) saturate(1.5) brightness(0.3); z-index: 0;
}
.bg-mask { position: absolute; inset: 0; background: var(--mask-overlay); z-index: 1; }

/* 顶部数据 */
.celestial-header {
  position: absolute; top: calc(var(--safe-top, 44px) + 15px); left: 0; width: 100%;
  text-align: center; z-index: 10; display: flex; flex-direction: column; align-items: center; gap: 4px;
}
.date-line { font-size: 11px; letter-spacing: 4px; color: var(--text-sub); text-transform: uppercase; }
.time-line { font-size: 42px; font-weight: 900; letter-spacing: -2px; text-shadow: 0 0 20px var(--accent-glow); font-family: ui-monospace, monospace; }
.time-line .colon { animation: blink 1s step-end infinite; }
.time-line .ampm { font-size: 12px; margin-left: 6px; opacity: 0.7; }
.rune-stats {
  display: flex; gap: 16px; font-size: 11px; color: var(--text-sub);
  background: var(--glass-base); padding: 6px 16px; border-radius: 20px;
  border: 1px solid var(--card-border); backdrop-filter: blur(8px); margin-top: 4px;
}

/* 漂浮塔罗牌阵 */
.tarot-spread {
  position: absolute;
  top: 22%; 
  left: 0; right: 0;
  display: flex; flex-wrap: wrap; justify-content: center;
  gap: 6px 10px; padding: 0 20px; z-index: 20;
}
.tarot-card {
  width: 56px; height: 84px;
  background: var(--glass-base);
  border: 1px solid var(--card-border);
  border-radius: 6px;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: 4px; backdrop-filter: blur(10px);
  box-shadow: 0 6px 15px rgba(0,0,0,0.4), inset 0 0 10px var(--card-glow);
  transition: all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  cursor: pointer; position: relative; overflow: hidden;
}
/* 华丽牌背 */
.tarot-card::before {
  content: ""; position: absolute; inset: 3px; border: 1px solid var(--card-border); border-radius: 3px;
  background: 
    radial-gradient(circle, transparent 20%, var(--card-border) 22%, transparent 25%),
    repeating-conic-gradient(from 0deg, transparent 0deg 15deg, var(--card-glow) 15deg 30deg),
    radial-gradient(circle at 20% 30%, var(--card-border) 1px, transparent 1px),
    radial-gradient(circle at 80% 70%, var(--card-border) 1px, transparent 1px),
    radial-gradient(circle at 50% 80%, var(--card-border) 1px, transparent 1px),
    radial-gradient(circle at 70% 20%, var(--card-border) 1px, transparent 1px),
    rgba(0, 0, 0, 0.6);
  opacity: 0.9;
}
.roman { font-size: 9px; font-family: ui-monospace, monospace; color: var(--text-sub); position: absolute; top: 6px; left: 8px; z-index: 2; }
.card-text { font-size: 10px; color: var(--text-main); text-align: center; padding: 0 2px; line-height: 1.1; word-break: break-all; z-index: 2; }

.tarot-card:nth-child(1) { transform: rotate(-4deg) translateY(5px); animation: float 4s ease-in-out infinite; }
.tarot-card:nth-child(2) { transform: rotate(2deg) translateY(-5px); animation: float 4.5s ease-in-out infinite 0.3s; }
.tarot-card:nth-child(3) { transform: rotate(-2deg) translateY(0px); animation: float 5s ease-in-out infinite 0.6s; }
.tarot-card:nth-child(4) { transform: rotate(5deg) translateY(-8px); animation: float 4.2s ease-in-out infinite 0.9s; }
.tarot-card:nth-child(5) { transform: rotate(-3deg) translateY(5px); animation: float 4.8s ease-in-out infinite 0.2s; }
.tarot-card:nth-child(6) { transform: rotate(1deg) translateY(-5px); animation: float 5.2s ease-in-out infinite 0.5s; }
.tarot-card:nth-child(7) { transform: rotate(-5deg) translateY(8px); animation: float 4.4s ease-in-out infinite 0.8s; }
.tarot-card:nth-child(8) { transform: rotate(3deg) translateY(-3px); animation: float 4.6s ease-in-out infinite 0.1s; }

.tarot-card:active { transform: scale(0.85) rotateY(20deg) !important; background: var(--card-glow); box-shadow: 0 0 25px var(--accent-glow), inset 0 0 15px var(--card-border); }

.tarot-card.start-card {
  background: rgba(255,255,255,0.05); border-color: var(--accent-glow);
  box-shadow: 0 0 20px var(--accent-glow), inset 0 0 15px var(--card-glow);
  animation: pulse 2s infinite alternate !important; transform: rotate(0deg) translateY(-10px) !important; 
}
.start-card .card-icon { font-size: 14px; color: var(--text-main); margin-bottom: 2px; text-shadow: 0 0 10px var(--accent-glow); z-index: 2; }
.start-card .roman { color: var(--text-main); opacity: 0.8; }
.start-card .card-text { font-weight: bold; letter-spacing: 1px; }

/* =========================================
   中间：星象罗盘 (填补空白，连接上下)
   ========================================= */
.astral-center-piece {
  position: absolute;
  top: 55%; 
  left: 50%;
  transform: translate(-50%, -50%);
  width: 130px;
  height: 130px;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 15;
  pointer-events: none; 
}

.astral-ring {
  position: absolute;
  border-radius: 50%;
  border: 1px dashed var(--card-border);
  opacity: 0.5;
}
.astral-ring.outer { inset: 0; animation: spin 25s linear infinite; border-style: solid; border-width: 1px; border-color: transparent; border-top-color: var(--card-border); }
.astral-ring.middle { inset: 15px; animation: spin 15s linear infinite reverse; border-color: var(--card-glow); }
.astral-ring.inner { inset: 30px; border-style: dotted; animation: spin 10s linear infinite; }

.astral-core {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  background: radial-gradient(circle, var(--glass-base) 0%, transparent 70%);
  padding: 10px;
  border-radius: 50%;
}
.core-moon {
  font-size: 20px;
  color: var(--text-main);
  margin-bottom: 2px;
  text-shadow: 0 0 10px var(--accent-glow);
}
.core-text {
  font-size: 10px;
  color: var(--text-sub);
  letter-spacing: 1px;
  margin-bottom: 2px;
}
.core-fortune {
  font-size: 9px;
  color: var(--card-border);
  letter-spacing: 1px;
  font-family: monospace;
  white-space: nowrap;
}

/* =========================================
   底部主控区：头像 + 自定义文字
   ========================================= */
.bottom-dock {
  position: absolute;
  bottom: calc(var(--safe-top, 44px) + 15px);
  left: 20px; right: 20px;
  display: flex; flex-direction: column; align-items: center; z-index: 30;
}
.portrait-wrap {
  position: relative; width: 85px; height: 85px; margin-bottom: 10px;
  display: flex; align-items: center; justify-content: center;
}
.portrait {
  width: 85px !important; height: 85px !important;
  aspect-ratio: 1 / 1 !important; border-radius: 50% !important;
  background-position: center; background-size: cover;
  border: 2px solid var(--card-border);
  box-shadow: 0 0 25px var(--accent-glow), inset 0 0 20px rgba(0,0,0,0.4);
  z-index: 2;
}
.halo-ring { position: absolute; border-radius: 50%; border: 1px dashed var(--card-border); }
.halo-ring.outer { inset: -12px; animation: spin 20s linear infinite; }
.halo-ring.inner { inset: 2px; border-style: solid; border-width: 1px; border-color: transparent; border-top-color: var(--card-border); animation: spin 10s linear infinite reverse; }

.custom-text-area { text-align: center; width: 100%; max-width: 280px; }
.char-name { font-size: 18px; font-weight: bold; color: var(--text-main); letter-spacing: 2px; margin-bottom: 2px; }
.char-sub { font-size: 10px; color: var(--text-sub); letter-spacing: 2px; margin-bottom: 8px; text-transform: uppercase; }
.char-line {
  font-size: 12px; line-height: 1.5; color: var(--text-sub);
  background: var(--glass-base); padding: 8px 16px; border-radius: 12px;
  border: 1px solid var(--card-border); backdrop-filter: blur(12px);
  box-shadow: 0 4px 15px rgba(0,0,0,0.2);
}

/* 动画 */
@keyframes spin { 100% { transform: rotate(360deg); } }
@keyframes blink { 50% { opacity: 0; } }
@keyframes float { 0%, 100% { margin-top: 0px; } 50% { margin-top: -6px; } }
@keyframes pulse { 0% { box-shadow: 0 0 15px var(--accent-glow); } 100% { box-shadow: 0 0 35px var(--accent-glow), 0 0 20px var(--card-border); } }

/* 入场动效 */
html.tp-fx:not(.tp-enter) .celestial-header, html.tp-fx:not(.tp-enter) .tarot-card, html.tp-fx:not(.tp-enter) .astral-center-piece, html.tp-fx:not(.tp-enter) .bottom-dock { opacity: 0; }
.tp-enter .celestial-header { animation: fadeIn 0.8s ease both; }
.tp-enter .astral-center-piece { animation: fadeIn 1.2s ease both 0.6s; }
.tp-enter .bottom-dock { animation: rise 1s cubic-bezier(.2,.8,.2,1) both 0.2s; }
.tp-enter .tarot-card { animation: rise 0.6s cubic-bezier(.2,.8,.2,1) both; }

.tp-enter .tarot-card:nth-child(1) { animation-delay: 0.3s; }
.tp-enter .tarot-card:nth-child(2) { animation-delay: 0.4s; }
.tp-enter .tarot-card:nth-child(3) { animation-delay: 0.5s; }
