.tp-enter .tarot-card:nth-child(4) { animation-delay: 0.6s; }
.tp-enter .tarot-card:nth-child(5) { animation-delay: 0.7s; }
.tp-enter .tarot-card:nth-child(6) { animation-delay: 0.8s; }
.tp-enter .tarot-card:nth-child(7) { animation-delay: 0.9s; }
.tp-enter .tarot-card:nth-child(8) { animation-delay: 1.0s; }
.tp-enter .tarot-card:nth-child(9) { animation-delay: 1.1s; }

@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
