  background-size: 30px 16px, 26px 26px, 26px 20px, 4px 4px, 4px 4px !important;
  background-repeat: no-repeat, no-repeat, no-repeat, repeat, repeat !important;
  background-position: right 18px bottom 14px, right 62px bottom 10px, right 102px bottom 12px, 0 0, 2px 2px !important;
}

